fn handle_loaded_typed_mcp<T: Native2dDocument>(
    loaded: Option<&mut LoadedTyped<T>>,
    operation: &str,
    arguments: Value,
    permissions: &AuthoringPermissions,
    label: &str,
) -> Result<Value, Native2dMcpCallFailure> {
    let loaded = loaded.ok_or_else(|| Native2dMcpCallFailure::no_document(label))?;
    match operation {
        "inspect" => {
            require_empty_arguments(arguments)?;
            loaded.mcp_inspect(permissions)
        }
        "validate" => {
            require_empty_arguments(arguments)?;
            loaded.mcp_validate(permissions)
        }
        "preview" => loaded.mcp_preview(permissions, decode_mcp(arguments)?),
        "apply" => loaded.mcp_apply(permissions, decode_mcp(arguments)?),
        _ => Err(Native2dMcpCallFailure::new(
            "mcp.unknown_tool",
            format!("unknown Native 2D typed-document operation `{operation}`"),
        )),
    }
}

